import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function DashboardProf() {
  const navigate = useNavigate();
  const [classes, setClasses] = useState([]);
  const [selectedClass, setSelectedClass] = useState(null);
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [studentsLoading, setStudentsLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    
    if (!token || user.role !== 'professeur') {
      navigate('/login');
      return;
    }
    
    fetchClasses();
  }, [navigate]);

  const fetchClasses = async () => {
    try {
      setLoading(true);
      console.log('Chargement des classes...');
      const response = await api.get('/api/professeur/classes');
      console.log('Réponse classes:', response.data);
      setClasses(response.data.classes || []);
    } catch (error) {
      console.error('Erreur chargement classes:', error);
      setError('Erreur lors du chargement des classes');
    } finally {
      setLoading(false);
    }
  };

  const fetchStudents = async (classId) => {
    try {
      setStudentsLoading(true);
      console.log(`Chargement des étudiants pour la classe ${classId}...`);
      
      // Essayer différentes routes possibles
      let studentsData = [];
      
      try {
        // Essayer la route principale
        const response = await api.get(`/api/professeur/classes/${classId}/students`);
        studentsData = response.data.students || [];
        console.log('Étudiants chargés via route principale:', studentsData);
      } catch (firstError) {
        console.log('Route principale échouée, essai route alternative...');
        
        // Essayer une route alternative
        try {
          const response = await api.get(`/api/classes/${classId}/students`);
          studentsData = response.data.students || response.data || [];
          console.log('Étudiants chargés via route alternative:', studentsData);
        } catch (secondError) {
          console.log('Route alternative échouée:', secondError);
          // Si les deux routes échouent, on garde un tableau vide
        }
      }
      
      setStudents(studentsData);
      
    } catch (error) {
      console.error('Erreur chargement étudiants:', error);
      setStudents([]);
    } finally {
      setStudentsLoading(false);
    }
  };

  const handleClassSelect = (classItem) => {
    setSelectedClass(classItem);
    fetchStudents(classItem.id);
  };

  const handleBackToClasses = () => {
    setSelectedClass(null);
    setStudents([]);
  };

  const handleCreateAssignment = (classItem) => {
    navigate('/create-assignment', { state: { classId: classItem.id, className: classItem.nom } });
  };

  const handleViewAssignments = (classItem) => {
    navigate('/prof-assignments', { state: { classId: classItem.id, className: classItem.nom } });
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement de vos classes...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <div style={styles.headerLeft}>
          <h1 style={styles.title}>
            {selectedClass ? `Classe: ${selectedClass.nom}` : 'Dashboard Professeur'}
          </h1>
          {selectedClass && (
            <button onClick={handleBackToClasses} style={styles.backButton}>
              ← Retour aux classes
            </button>
          )}
        </div>
        <div style={styles.headerActions}>
          <button onClick={handleLogout} style={styles.logoutButton}>
            Déconnexion
          </button>
        </div>
      </header>

      <main style={styles.main}>
        {error && (
          <div style={styles.errorAlert}>
            {error}
          </div>
        )}

        {!selectedClass ? (
          // Vue liste des classes
          <div style={styles.classesSection}>
            <div style={styles.sectionHeader}>
              <h2 style={styles.sectionTitle}>Mes Classes</h2>
              <span style={styles.counter}>
                {classes.length} classe{classes.length > 1 ? 's' : ''}
              </span>
            </div>

            {classes.length === 0 ? (
              <div style={styles.emptyState}>
                <div style={styles.emptyIcon}>🏫</div>
                <h3>Aucune classe assignée</h3>
                <p>Vos classes apparaîtront ici une fois assignées par l'administration.</p>
              </div>
            ) : (
              <div style={styles.classesGrid}>
                {classes.map((classItem) => (
                  <div key={classItem.id} style={styles.classCard}>
                    <div style={styles.classHeader}>
                      <h3 style={styles.className}>{classItem.nom}</h3>
                      <span style={styles.studentCount}>
                        {classItem.nombre_etudiants || 0} étudiant{classItem.nombre_etudiants > 1 ? 's' : ''}
                      </span>
                    </div>
                    
                    <div style={styles.classInfo}>
                      <p style={styles.classDescription}>
                        {classItem.description || 'Aucune description disponible'}
                      </p>
                      
                      <div style={styles.classMeta}>
                        <div style={styles.metaItem}>
                          <strong>Année:</strong> {classItem.annee_scolaire || 'Non spécifiée'}
                        </div>
                        <div style={styles.metaItem}>
                          <strong>Créée le:</strong> {classItem.date_creation ? new Date(classItem.date_creation).toLocaleDateString('fr-FR') : 'Date inconnue'}
                        </div>
                      </div>
                    </div>

                    <div style={styles.classActions}>
                      <button
                        onClick={() => handleClassSelect(classItem)}
                        style={styles.viewStudentsButton}
                      >
                        👥 Voir les étudiants
                      </button>
                      <button
                        onClick={() => handleCreateAssignment(classItem)}
                        style={styles.createAssignmentButton}
                      >
                        📝 Créer un devoir
                      </button>
                      <button
                        onClick={() => handleViewAssignments(classItem)}
                        style={styles.viewAssignmentsButton}
                      >
                        📚 Voir les devoirs
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : (
          // Vue détail d'une classe avec étudiants
          <div style={styles.studentsSection}>
            <div style={styles.sectionHeader}>
              <h2 style={styles.sectionTitle}>
                Étudiants - {selectedClass.nom}
              </h2>
              <span style={styles.counter}>
                {students.length} étudiant{students.length > 1 ? 's' : ''}
              </span>
            </div>

            {studentsLoading ? (
              <div style={styles.loadingStudents}>
                <div style={styles.smallSpinner}></div>
                <p>Chargement des étudiants...</p>
              </div>
            ) : students.length === 0 ? (
              <div style={styles.emptyState}>
                <div style={styles.emptyIcon}>👥</div>
                <h3>Aucun étudiant trouvé</h3>
                <p>
                  {selectedClass.nombre_etudiants > 0 
                    ? "Les étudiants n'ont pas pu être chargés. Vérifiez la connexion ou contactez l'administration."
                    : "Aucun étudiant n'est inscrit dans cette classe pour le moment."
                  }
                </p>
                <button 
                  onClick={() => fetchStudents(selectedClass.id)} 
                  style={styles.retryButton}
                >
                  🔄 Réessayer
                </button>
              </div>
            ) : (
              <div style={styles.studentsGrid}>
                {students.map((student) => (
                  <div key={student.id} style={styles.studentCard}>
                    <div style={styles.studentHeader}>
                      <h3 style={styles.studentName}>
                        {student.prenom} {student.nom}
                      </h3>
                      <span style={styles.studentId}>
                        #{student.id || student.matricule}
                      </span>
                    </div>
                    
                    <div style={styles.studentInfo}>
                      <div style={styles.metaItem}>
                        <strong>Email:</strong> {student.email || 'Non disponible'}
                      </div>
                      <div style={styles.metaItem}>
                        <strong>Inscrit le:</strong> {student.date_inscription ? new Date(student.date_inscription).toLocaleDateString('fr-FR') : 'Date inconnue'}
                      </div>
                      <div style={styles.metaItem}>
                        <strong>Statut:</strong> 
                        <span style={{
                          color: student.statut === 'actif' ? '#48bb78' : '#e53e3e',
                          fontWeight: '600',
                          marginLeft: '0.5rem'
                        }}>
                          {student.statut || 'Actif'}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            <div style={styles.classActions}>
              <button
                onClick={() => handleCreateAssignment(selectedClass)}
                style={styles.createAssignmentButton}
              >
                📝 Créer un devoir pour cette classe
              </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

